import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    # Extract all URLs from the string
    url_pattern = r'https?://[^\s<>"\'()]+'
    raw_urls = re.findall(url_pattern, myString)

    # Extract domains from each URL
    domains = set()
    for url in raw_urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        # Remove port number if present
        if ':' in domain:
            domain = domain.split(':')[0]
        if domain:
            domains.add(domain)

    # Get geolocation for each domain
    result = {}
    for domain in domains:
        try:
            response = requests.get(
                f"https://api.ipapi.com/{domain}?access_key={API_KEY}",
                timeout=10
            )
            if response.status_code == 200:
                data = response.json()
                result[domain] = data
            else:
                result[domain] = None
        except requests.RequestException:
            result[domain] = None

    return result

import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    # Step 1: Extract all URLs from the string
    url_pattern = re.compile(r'https?://[^\s]+')
    raw_urls = url_pattern.findall(myString)

    # Step 2: Extract domains from each URL
    domains = set()
    for url in raw_urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        if domain:
            domains.add(domain)

    # Step 3: Get geolocation data for each domain using IP API
    result = {}
    for domain in domains:
        try:
            response = requests.get(f'https://api.ipapi.com/{domain}?access_key={API_KEY}', timeout=10)
            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    result[domain] = data
                else:
                    result[domain] = None
            else:
                result[domain] = None
        except requests.RequestException:
            result[domain] = None

    return result

import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    """
    Extract and validate a public IP address from a JSON response.

    Args:
        ip_address: A string containing JSON with an IP address

    Returns:
        str: The public IP address, or 'Invalid IP address received' if invalid
    """
    try:
        # Parse the JSON string
        data = json.loads(ip_address)

        # Extract IP address from the JSON data
        # Handle both direct string and nested structures
        if isinstance(data, str):
            ip_str = data
        elif isinstance(data, dict):
            # Look for common IP address keys
            ip_str = data.get('ip', data.get('IP', data.get('address', data.get('query', ''))))
        else:
            return 'Invalid IP address received'

        # Validate the IP address format
        if not re.match(IP_REGEX, ip_str):
            return 'Invalid IP address received'

        # Validate each octet is between 0 and 255
        octets = ip_str.split('.')
        if len(octets) != 4:
            return 'Invalid IP address received'

        for octet in octets:
            try:
                value = int(octet)
                if value < 0 or value > 255:
                    return 'Invalid IP address received'
            except ValueError:
                return 'Invalid IP address received'

        return ip_str

    except (json.JSONDecodeError, AttributeError, TypeError):
        return 'Invalid IP address received'

