import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    """
    Extract recipient email addresses and names from JSON-formatted string,
    and send the names in an email.

    Args:
        input_data: JSON string containing recipient information
        smtp_server: SMTP server address
        smtp_port: SMTP server port
        email_address: Sender's email address
        email_password: Sender's email password
        smtp: Optional SMTP connection object (for testing)

    Returns:
        dict: Contains 'list' key with extracted names
    """
    # Parse JSON input
    try:
        if input_data is None:
            return {"list": []}

        if isinstance(input_data, str):
            data = json.loads(input_data)
        else:
            data = input_data

        # Extract names and email addresses
        extracted_names = []

        # Handle different JSON structures
        if isinstance(data, dict):
            # Check for common patterns
            if 'recipients' in data:
                recipients = data['recipients']
            elif 'contacts' in data:
                recipients = data['contacts']
            elif 'to' in data:
                recipients = data['to']
            else:
                recipients = [data]

            if isinstance(recipients, list):
                for item in recipients:
                    if isinstance(item, dict):
                        # Extract name from various possible keys
                        name = item.get('name') or item.get('Name') or item.get('full_name') or item.get('FullName')
                        email = item.get('email') or item.get('Email') or item.get('email_address') or item.get('EmailAddress')
                        if name and email:
                            extracted_names.append(name)
                    elif isinstance(item, str):
                        # Could be a single name or email
                        if '@' not in item:
                            extracted_names.append(item)
            elif isinstance(recipients, dict):
                name = recipients.get('name') or recipients.get('Name')
                email = recipients.get('email') or recipients.get('Email')
                if name and email:
                    extracted_names.append(name)

        elif isinstance(data, list):
            for item in data:
                if isinstance(item, dict):
                    name = item.get('name') or item.get('Name') or item.get('full_name')
                    email = item.get('email') or item.get('Email')
                    if name and email:
                        extracted_names.append(name)

        # Prepare email content
        if extracted_names:
            subject = "Extracted Names"
            body = "\n".join(extracted_names)
            message = f"Subject: {subject}\n\n{body}"

            # Send email
            try:
                if smtp is None:
                    # Create SMTP connection
                    server = smtplib.SMTP(smtp_server, smtp_port)
                    server.starttls()
                    server.login(email_address, email_password)
                else:
                    server = smtp

                # Send to self (or could be configured for specific recipient)
                server.sendmail(email_address, email_address, message)

                if smtp is None:
                    server.quit()

            except Exception as e:
                print(f"Error sending email: {e}")
                # Continue execution - return names even if email fails

        return {"list": extracted_names}

    except json.JSONDecodeError as e:
        print(f"Error parsing JSON: {e}")
        return {"list": []}
    except Exception as e:
        print(f"Unexpected error: {e}")
        return {"list": []}

import collections
import json
import os
def task_func(directory_path: str) -> dict:
    """
    Counts the total appearances of all keys across all JSON files in the specified directory.

    Args:
        directory_path (str): Path to the directory containing JSON files.

    Returns:
        dict: A dictionary with keys from JSON files as keys and their total counts as values.
    """
    key_counter = collections.Counter()

    # Iterate over all files in the directory
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            filepath = os.path.join(directory_path, filename)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    # If the JSON file contains a dictionary, count its keys
                    if isinstance(data, dict):
                        key_counter.update(data.keys())
                    # If it's a list of dictionaries, count keys from each
                    elif isinstance(data, list):
                        for item in data:
                            if isinstance(item, dict):
                                key_counter.update(item.keys())
            except (json.JSONDecodeError, IOError) as e:
                # Skip files that can't be read or parsed
                continue

    return dict(key_counter)

