import os
def task_func(directory_path: str) -> dict:
    """
    Counts the total appearances of all keys across all JSON files in the given directory.

    Args:
        directory_path (str): Path to the directory containing JSON files.

    Returns:
        dict: Dictionary with keys from JSON files and their total counts.
    """
    key_counter = collections.Counter()

    # Iterate over all files in the directory
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            filepath = os.path.join(directory_path, filename)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    if isinstance(data, dict):
                        # Count each key in the JSON object
                        for key in data.keys():
                            key_counter[key] += 1
                    elif isinstance(data, list):
                        # If JSON is a list of objects, count keys from each object
                        for item in data:
                            if isinstance(item, dict):
                                for key in item.keys():
                                    key_counter[key] += 1
            except (json.JSONDecodeError, IOError) as e:
                # Skip files that can't be read or parsed
                print(f"Skipping file {filename}: {e}")
                continue

    return dict(key_counter)

