import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    # Check if file exists
    if not os.path.exists(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    # Load JSON from file
    with open(file_path, 'r') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON format in file")

    # Validate that data is an object
    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    # Validate required fields exist
    for field in INPUT_JSON["required"]:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")

    # Validate types of each property
    for field, props in INPUT_JSON["properties"].items():
        expected_type = props["type"]
        if field in data:
            if not isinstance(data[field], expected_type):
                raise ValueError(f"Field '{field}' should be of type {expected_type.__name__}, got {type(data[field]).__name__}")

    # Validate email format if present
    if "email" in data:
        email = data["email"]
        if not isinstance(email, str) or not re.match(EMAIL_REGEX, email, re.IGNORECASE):
            raise ValueError("Invalid email format")

    # Check requested attribute exists
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON object")

