import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    # Read the JSON file
    with open(input_file, 'r') as f:
        data = json.load(f)

    # Ensure data is a list of dictionaries
    if not isinstance(data, list):
        raise ValueError("Input JSON must contain a list of dictionaries")

    # Collect numeric values for each key
    values_dict = defaultdict(list)

    for record in data:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            # Check if value is numeric (int or float) and not None
            if value is not None and isinstance(value, (int, float)):
                # Also check for NaN (float('nan'))
                if not (isinstance(value, float) and np.isnan(value)):
                    values_dict[key].append(value)

    # Calculate mean and median for each key
    results = {}
    for key, values in values_dict.items():
        if values:  # Only process if we have numeric values
            results[key] = {
                'mean': np.mean(values),
                'median': np.median(values)
            }

    # Convert to DataFrame and sort by index (variable names)
    df = pd.DataFrame.from_dict(results, orient='index')
    df.index.name = 'variable'
    df = df.sort_index()

    return df

